alter table badges add column if not exists tier text not null default 'bronze';
alter table badges add column if not exists grp text not null default 'tasks';
alter table badges add column if not exists sort_order int not null default 0;
alter table badges drop constraint if exists badges_kind_check;
alter table student_badges add column if not exists period text;   -- مفتاح الشهر الهجري لوسام تميّز الشهر (مثل 1448-06)
drop index if exists student_badges_once;
create unique index student_badges_once on student_badges (student_id, badge_id, coalesce(period, ''));
alter table reward_rules add column if not exists monthly_sessions int not null default 8;
alter table reward_rules add column if not exists monthly_models int not null default 2;
alter table reward_rules add column if not exists monthly_independent int not null default 30;

delete from student_badges where badge_id in (select id from badges where code not in ('first_session', 'sessions_5', 'sessions_20', 'sessions_50', 'std_1', 'std_5', 'dom_number', 'dom_algebra', 'dom_geometry', 'dom_data', 'std_19', 'model_1', 'model_80', 'timss_expert', 'persistence_3', 'comeback', 'personal_best', 'monthly_excellence'));
delete from badges where code not in ('first_session', 'sessions_5', 'sessions_20', 'sessions_50', 'std_1', 'std_5', 'dom_number', 'dom_algebra', 'dom_geometry', 'dom_data', 'std_19', 'model_1', 'model_80', 'timss_expert', 'persistence_3', 'comeback', 'personal_best', 'monthly_excellence');
